            ['kod' => 'MAK-056', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Toz oluşumu', 'tehlike' => 'Plastik tozunun solunması', 'risk' => 'Solunum yolu etkilenmesi', 'mevcut_onlem' => 'Tozu kaynağında kapalı emişle toplayın. Basınçlı hava ile ortama yaymayın; malzemeye uygun filtre ve temizlik ekipmanı kullanıp maruziyeti değerlendirin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde); K5', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-057', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Yanıcı toz varsa', 'tehlike' => 'Toz birikimi ve tutuşturucu kaynak', 'risk' => 'Yangın veya toz patlaması', 'mevcut_onlem' => 'Tozun yanıcılığını malzeme verisi/testle belirleyin. Patlayıcı ortam oluşabiliyorsa uygun bölgeleme, ekipman ve toz toplama tedbirlerini uzman değerlendirmesiyle tasarlayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde); K5', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'MAK-058', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Acil durdurma', 'tehlike' => 'Durdurma butonunun işlevsizliği', 'risk' => 'Yaralanmanın ağırlaşması', 'mevcut_onlem' => 'Besleme ve boşaltma çalışma konumlarından güvenli durdurmayı sağlayın. Rotorun güvenli duruşunu ve reset sonrası kendiliğinden başlamadığını test edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 13850 (acil stop işlevi için); K5', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-059', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Güç bağlantısı', 'tehlike' => 'Kablo ve motor yalıtım arızası', 'risk' => 'Elektrik çarpması', 'mevcut_onlem' => 'Kabloyu darbe ve tozdan koruyun. Motor koruması ile topraklama sürekliliğini kontrol ettirin; arızalı ekipmanı etiketleyip elektrik onarımı bitene kadar kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde); K5', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-060', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Makine üstü aletler', 'tehlike' => 'Aletlerin düşmesi veya beslemeye girmesi', 'risk' => 'Çarpma, kırıcı hasarı', 'mevcut_onlem' => 'Makine üstünü depolama alanı olarak kullanmayın. Aletler için sabit pano oluşturun; vardiya başında besleme çevresini yabancı cisim yönünden kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde); K5', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-061', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Malzeme sıkışması', 'tehlike' => 'Çalışırken hazne içine uzanma', 'risk' => 'Kesilme ve uzuv kaybı', 'mevcut_onlem' => 'Tıkanmada durdurun, kilitleyin ve rotor duruşunu doğrulayın. Hazne desteklerini yerleştirin; tanımlı aparatla müdahale sonrası tüm korumaları yeniden kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde); K5', 'olasilik' => 6.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'MAK-062', 'bolum' => 'Plastik kırıcı / granülatör', 'faaliyet' => 'Besleme ergonomisi', 'tehlike' => 'Ağır hurdayı uygunsuz yükseklikten verme', 'risk' => 'Bel zorlanması ve denge kaybı', 'mevcut_onlem' => 'Besleme yüksekliğini ve malzeme ağırlığını azaltın. Uygun kaldırma/taşıma yardımcısı kullanın; hazneye ulaşmak için kasa veya makine üzerine çıkmayı önleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde); K5', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
        ]],
        'atolye_torna_tezgahi' => ['Atölye – Torna tezgâhı', [
            ['kod' => 'TFD-001', 'bolum' => 'Torna', 'faaliyet' => 'Ayna çevresinde çalışma', 'tehlike' => 'Korumasız dönen ayna ve çeneler', 'risk' => 'Kaptırma, uzuv kaybı, ölüm', 'mevcut_onlem' => 'Ayna ve çıkıntılı çenelere erişimi önleyen, makineye uygun koruyucu yerleştirin. Kilitleme gerekiyorsa emniyet devresiyle birlikte doğrulayın; koruyucuyu baypas etmeyin. Koruyucu kesici bölgesindeki diğer erişim risklerini de kapsayacak şekilde değerlendirilmelidir.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-002', 'bolum' => 'Torna', 'faaliyet' => 'Ayna anahtarını kullanma', 'tehlike' => 'Anahtarın aynada unutulması', 'risk' => 'Anahtar fırlaması ve ağır yaralanma', 'mevcut_onlem' => 'Sıkma işlemi biter bitmez anahtarı çıkarıp belirlenmiş yere bırakın. Uygun kendiliğinden ayrılan anahtar veya üretici onaylı teknik önlemi değerlendirin. Başlatma öncesi kontrolü uygulayın; anahtar aynadayken motoru çalıştırmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-003', 'bolum' => 'Torna', 'faaliyet' => 'İş parçasını aynaya bağlama', 'tehlike' => 'Yetersiz kavrama, aşınmış çene veya gevşek sıkma', 'risk' => 'Parça fırlaması ve ölüm', 'mevcut_onlem' => 'Çene tipi ve kavrama boyunu parça geometrisine göre seçin. Ayna ve çene kapasitesi ile üretici sıkma şartlarını doğrulayın. Hasarlı çeneyi değiştirin; ilk çalıştırma öncesi sıkma ve serbest dönüş alanını güvenli durumda kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-004', 'bolum' => 'Torna', 'faaliyet' => 'Devir seçme', 'tehlike' => 'Ayna, çene veya iş parçası sınırının aşılması', 'risk' => 'Parça ve çene fırlaması', 'mevcut_onlem' => 'Ayna, bağlantı, parça çapı ve balans şartları için en düşük izin verilen hız sınırını esas alın. Büyük çap ve dengesiz parçada uygun düşük devir belirleyin. Hız etiketlerini görünür tutun; sınırı sadece motor kapasitesine göre seçmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-005', 'bolum' => 'Torna', 'faaliyet' => 'Uzun çubuk işleme', 'tehlike' => 'Mil arkasından çıkan çubuğun savrulması', 'risk' => 'Çarpma, kaptırma ve ölüm', 'mevcut_onlem' => 'Mil arkasından çıkan çubuğu boyu boyunca uygun muhafazalı destek sistemi içinde tutun. Çap, serbest boy ve hızın uyumunu doğrulayın. Geçiş yoluna açık çubuk bırakmayın; doğaçlama boru ve dengesiz sehpaya güvenmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-006', 'bolum' => 'Torna', 'faaliyet' => 'Uzun ince parça tornalama', 'tehlike' => 'Desteksiz parçanın eğilmesi veya kırılması', 'risk' => 'Parça savrulması, ağır yaralanma', 'mevcut_onlem' => 'Parçaya uygun punta, sabit veya gezer yatak kullanın. Destek konumunu, yağlamayı ve parça rijitliğini kontrol edin. Kesme kuvveti ve devir sınırını belirleyin; titreşim oluştuğunda güvenli duruşla nedeni giderin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-007', 'bolum' => 'Torna', 'faaliyet' => 'Punta ve gezer başlık ayarı', 'tehlike' => 'Kilitsiz gövde, gevşek punta veya yetersiz kavrama', 'risk' => 'Parçanın kurtulması ve ezilme', 'mevcut_onlem' => 'Gezer başlığı yatağa ve punta milini gerekli konuma üretici yöntemine göre sabitleyin. Punta deliği ve temasın uygunluğunu kontrol edin. Ayarı tam duruşta yapın; elinizi parça ile punta arasına koymayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-008', 'bolum' => 'Torna', 'faaliyet' => 'Yüzey plakasıyla işleme varsa', 'tehlike' => 'Dengesiz veya çıkıntılı bağlama elemanları', 'risk' => 'Çarpma, fırlama ve ölüm', 'mevcut_onlem' => 'Plaka ve bağlama elemanlarının kapasitesini doğrulayın. Çıkıntıların dönüş hacmini koruyun, balansı ve düşük devir ihtiyacını değerlendirin. Bağlama cıvatalarını üretici torkuyla sıkın; kontrol tamamlanmadan çalıştırmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-009', 'bolum' => 'Torna', 'faaliyet' => 'Kalem bağlama', 'tehlike' => 'Gevşek kalem, uzun çıkıntı veya yanlış merkez yüksekliği', 'risk' => 'Kalem kırılması, sıçrama ve kesilme', 'mevcut_onlem' => 'Kalemi rijit ve uygun boyda bağlayın; merkez yüksekliğini ve takım tutucu sıkılığını doğrulayın. Uygun altlık kullanın; üst üste gelişigüzel malzeme sıkıştırmayın. Aşınmış kesiciyi güvenli duruşta değiştirin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-010', 'bolum' => 'Torna', 'faaliyet' => 'Otomatik ilerleme kullanma', 'tehlike' => 'Araba veya kalemin aynaya çarpması', 'risk' => 'Takım/parça kırılması ve sıkışma', 'mevcut_onlem' => 'İlerleme yönünü ve yaklaşma sınırını çalıştırmadan doğrulayın. Varsa üretici sınırlandırıcılarını ve durdurmayı test edin. Kör ilerleme veya tezgâhı gözetimsiz bırakmayı önleyin; ayarı tam duruşta yapın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-011', 'bolum' => 'Torna', 'faaliyet' => 'Vida açma', 'tehlike' => 'Somun kavramasının yanlış kullanımı ve omuza yaklaşma', 'risk' => 'Çarpışma, kalem kırılması', 'mevcut_onlem' => 'Vida adımı, ilerleme ve duruş mesafesini iş planında belirleyin. Üretici yöntemine uygun kontrollü devir kullanın. Geri dönüş ve kavrama işlemini yetkin operatör yapsın; hareketli parçada elle kontrol yapmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'TFD-012', 'bolum' => 'Torna', 'faaliyet' => 'Kesme ve kanal açma', 'tehlike' => 'Takım sıkışması ve kopan parçanın düşmesi', 'risk' => 'Fırlama, kesik ve ayak yaralanması', 'mevcut_onlem' => 'Kesici hizasını, uygun çıkıntıyı ve kesme parametresini doğrulayın. Ayrılan parçayı elle yakalamayın; uygun toplama/destek düzeneği kullanın. Düşecek parçanın altında uzuv bulundurmayın; uzun talaşı elle çekmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'TFD-013', 'bolum' => 'Torna', 'faaliyet' => 'İç çap tornalama', 'tehlike' => 'Uzun baranın esnemesi veya tutucudan çıkması', 'risk' => 'Takım kırılması ve parça hasarı', 'mevcut_onlem' => 'Bara çapı ve çıkıntısını üretici sınırlarına uygun seçin. Rijit bağlayın; titreşim halinde parametreyi ve desteklemeyi yeniden değerlendirin. İç yüzeyi hareket sürerken elle veya aletle temizlemeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'TFD-014', 'bolum' => 'Torna', 'faaliyet' => 'Zımpara veya polisaj', 'tehlike' => 'Zımpara bezinin dönen parçaya sarılması', 'risk' => 'El-kol kaptırma, uzuv kaybı', 'mevcut_onlem' => 'Elle tutulan bezi dönen parçaya dolamayın. İşi ayrı uygun finisaj makinesine aktarın veya yalnız üretici onaylı, eli tehlikeden uzak tutan düzen kullanın. Tornada eldivenle polisaj yapmayın; iş yöntemini yazılı onaylayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-015', 'bolum' => 'Torna', 'faaliyet' => 'Ölçme ve çapak kontrolü', 'tehlike' => 'Dönen parçaya kumpas veya el uzatma', 'risk' => 'Kaptırma, kesilme ve fırlama', 'mevcut_onlem' => 'Mil tamamen durmadan ölçüm, elle kontrol ve çapak alma yapmayın. Yeniden hareketi önleyin; ölçü aletini tezgâh üstünden uzaklaştırın. Duruşu el veya bezle hızlandırmayın; güvenli ölçüm istasyonu oluşturun.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-016', 'bolum' => 'Torna', 'faaliyet' => 'Talaş kırma ve uzaklaştırma', 'tehlike' => 'Uzun sarmal talaşın dolaşması', 'risk' => 'Derin kesik, kaptırma ve yanık', 'mevcut_onlem' => 'Uygun talaş kırıcı ve kesme parametresi seçin. Talaşı duruş ve gerekli izolasyon sonrası kanca/fırçayla alın; elle çekmeyin. Toplanmış talaşı dönen parçadan kurtarmaya çalışmayın. Keskin atığı uygun kapta biriktirin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-017', 'bolum' => 'Torna', 'faaliyet' => 'Vida mili ve transmisyon çevresi', 'tehlike' => 'Açık vida mili, kayış ve dişliye erişim', 'risk' => 'Kaptırma ve ezilme', 'mevcut_onlem' => 'Erişilebilir aktarma elemanlarını üreticiye uygun koruyun. Yağlama ve bakım açıklıklarını değerlendirin; koruyucusuz çalışmayı önleyin. Temizlik veya dişli değiştirmede enerji izolasyonu uygulayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-018', 'bolum' => 'Torna', 'faaliyet' => 'Ayna değiştirme', 'tehlike' => 'Ağır aynanın düşmesi ve milin istemsiz dönmesi', 'risk' => 'El-ayak ezilmesi', 'mevcut_onlem' => 'Makineyi izole edin; uygun ayna taşıma desteği veya kaldırma yardımcısı kullanın. Bağlantı yöntemini üretici talimatıyla uygulayın. Tezgâhı motor gücüyle ayna sökme amacıyla zorlamayın; montaj sonrası bağlantıyı kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'TFD-019', 'bolum' => 'Torna', 'faaliyet' => 'Mil frenleme ve yön değiştirme', 'tehlike' => 'Tam duruş olmadan uygunsuz tersleme', 'risk' => 'Ayna gevşemesi ve mekanik arıza', 'mevcut_onlem' => 'Fren ve yön değiştirmeyi üreticinin öngördüğü şekilde kullanın. Vidalı ayna bağlantısında ters çalışma uygunluğunu ayrıca doğrulayın. Aynayı elle tutarak durdurmayın; fren arızasında makineyi kullanım dışı bırakın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-020', 'bolum' => 'Torna', 'faaliyet' => 'İki kişiyle çalışma', 'tehlike' => 'Bir kişinin diğerini görmeden tezgâhı başlatması', 'risk' => 'Kaptırma ve ağır yaralanma', 'mevcut_onlem' => 'Normal işletimde kumanda sorumlusunu belirleyin. Ortak müdahalede kişisel/grup kilitleme uygulayın. Parça yükleyen kişi güvenli alana geçmeden başlatmayın; sözlü uyarıyı tek koruma olarak kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-021', 'bolum' => 'Torna', 'faaliyet' => 'Acil durdurma kullanımı', 'tehlike' => 'Durdurma butonunun erişilemez veya işlevsiz olması', 'risk' => 'Tehlikeli hareketin sürmesi, ağır yaralanma', 'mevcut_onlem' => 'Operatör ve müdahale noktalarından erişilebilen acil durdurma düzenini kontrol edin. Tüm ilişkili tehlikeli hareketlerin güvenli tepki verdiğini test edin. Butonun çözülmesi tek başına yeniden başlatmasın. Acil durdurmayı enerji izolasyonu yerine kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-022', 'bolum' => 'Torna', 'faaliyet' => 'Enerji kesintisi sonrası çalışma', 'tehlike' => 'Enerji geri geldiğinde kendiliğinden hareket', 'risk' => 'Sıkışma, ezilme, ölüm', 'mevcut_onlem' => 'Elektrik veya hava basıncı geri geldiğinde otomatik çevrim başlamasını önleyin. Güvenli reset ve ayrı başlatma işlemi tanımlayın. Testi tehlike alanı boşken yetkili personelle yapın; kesinti sonrası parça ve takım konumunu kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-023', 'bolum' => 'Torna', 'faaliyet' => 'Elektrik panosuna müdahale', 'tehlike' => 'Canlı iletken ve kısa devre enerjisi', 'risk' => 'Elektrik çarpması, yanık, ölüm', 'mevcut_onlem' => 'Panoyu kilitli tutun; müdahaleyi yetkili elektrik personeline verin. Beslemeyi ayırıp kişisel kilitleme yapın, uygun cihazla gerilimsizliği doğrulayın. Canlı çalışma rutin yöntem olmasın. İşe özgü elektriksel risk ve uygun koruyucu ekipman değerlendirilsin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–7; Ek I: elektrik tehlikesi; Ek III: ilgili tesisat | Makina Emniyeti Yön.: Ek I: 1.5.1, 1.6.3 | Standart/teknik: IEC 60204-1; üretici elektrik şeması', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-024', 'bolum' => 'Torna', 'faaliyet' => 'Gövde ve kablo tesisatı', 'tehlike' => 'Koruyucu iletken hatası veya yalıtım hasarı', 'risk' => 'Dokunma gerilimi, yangın, ölüm', 'mevcut_onlem' => 'Koruyucu iletken sürekliliği ve elektriksel koruma düzenini yetkin kişiye doğrulatın. Sıvı girişini, ezilmiş kabloyu ve uygunsuz ekleri giderin. İlgili tesisatın mevzuata tabi kontrollerini takip edin; makine için keyfî tek yıllık kontrol süresi atamayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–7; Ek I: elektrik tehlikesi; Ek III: ilgili tesisat | Makina Emniyeti Yön.: Ek I: 1.5.1, 1.6.3 | Standart/teknik: IEC 60204-1; üretici elektrik şeması', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-025', 'bolum' => 'Torna', 'faaliyet' => 'Bakım ve arıza giderme', 'tehlike' => 'Tüm enerji kaynaklarının ayrılmaması', 'risk' => 'Beklenmeyen hareket, ezilme, ölüm', 'mevcut_onlem' => 'Elektrik, hava, hidrolik, yerçekimi ve depolanmış enerjiyi gösteren makineye özgü EKED prosedürü hazırlayın. Ayırın, kişisel kilit ve etiket uygulayın, enerjiyi boşaltın veya güvenle tutun. İşe başlamadan sıfır enerjiyi doğrulayın; grup ve vardiya kilit devrini tanımlayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: bakım ve enerji ayırma; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.6.1, 1.6.3 | Standart/teknik: ISO 14118; ISO 12100; üretici izolasyon talimatı', 'olasilik' => 6.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-026', 'bolum' => 'Torna', 'faaliyet' => 'Bakım sonrası devreye alma', 'tehlike' => 'Muhafaza, kilit veya kablonun yanlış takılması', 'risk' => 'Emniyet işlevinin kaybı ve ağır yaralanma', 'mevcut_onlem' => 'Alet ve personel sayımı yapın. Muhafazaları ve bağlantıları geri takın. Kilitleri prosedürüne göre kaldırın; emniyet fonksiyonlarını kontrollü test edin. Yetkili teslim formu olmadan üretime geçmeyin; değişiklik varsa risk değerlendirmesini yenileyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-027', 'bolum' => 'Torna', 'faaliyet' => 'Ağır parça ve fikstür yükleme', 'tehlike' => 'Uygunsuz kaldırma, sapan veya bağlantı', 'risk' => 'Yük düşmesi, ezilme, ölüm', 'mevcut_onlem' => 'Ağırlığı ve ağırlık merkezini belirleyin. Uygun kapasiteli kaldırma ekipmanı ve aksesuar kullanın; güncel kontrol durumunu doğrulayın. Yük yolunu ayırın, askıdaki yükün altında bulunmayın. Parça güvenli oturmadan sapanı çözmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek II: kaldırma ekipmanı; Ek III: ilgili ekipman grubu | Makina Emniyeti Yön.: Ek I: 1.1.5; kaldırma donanımı için ilgili hükümler | Standart/teknik: Kaldırma planı; ekipman ve aksesuar üretici talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 40.0],
            ['kod' => 'TFD-028', 'bolum' => 'Torna', 'faaliyet' => 'Elle malzeme taşıma', 'tehlike' => 'Ağır veya dengesiz yük ve tekrarlı kaldırma', 'risk' => 'Bel-sırt ve kas iskelet rahatsızlığı', 'mevcut_onlem' => 'Parça kütlesi, kavrama ve taşıma sıklığını değerlendirin. Kaldırma yardımcısı ve yükseklik ayarlı araba kullanın. Malzemeyi erişilebilir yerde konumlandırın; görev düzenlemesini destek olarak uygulayın. Her yük için tek bir güvenli kilogram sınırı varsaymayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 9: ergonomi; Ek II: kullanım koşulları | Makina Emniyeti Yön.: Ek I: 1.1.6 | Standart/teknik: ISO 12100; işe özgü ergonomi ve elle taşıma değerlendirmesi', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'TFD-029', 'bolum' => 'Torna', 'faaliyet' => 'Uzun süreli operatör çalışması', 'tehlike' => 'Uzanma, bükülme, ayakta kalma ve ekran konumu', 'risk' => 'Kas iskelet zorlanması ve yorgunluk', 'mevcut_onlem' => 'Panel, takım rafı ve parça istasyonunu çalışana uygun erişimde düzenleyin. Kayma riski yaratmayan çalışma yüzeyi sağlayın. İş-mola düzenini iş yüküne göre belirleyin; çalışan geri bildirimleriyle ergonomik iyileştirmeyi kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 9: ergonomi; Ek II: kullanım koşulları | Makina Emniyeti Yön.: Ek I: 1.1.6 | Standart/teknik: ISO 12100; işe özgü ergonomi ve elle taşıma değerlendirmesi', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'TFD-030', 'bolum' => 'Torna', 'faaliyet' => 'Gürültülü kesme', 'tehlike' => 'Yüksek gürültüye maruziyet', 'risk' => 'İşitme kaybı ve iletişim güçlüğü', 'mevcut_onlem' => 'Maruziyeti uygun ölçümle belirleyin. Takım, balans, kesme parametresi ve kabin akustik bakımını iyileştirin. Ölçüme göre teknik ve organizasyonel önlemleri uygulayın; gerekli kulak koruyucusunu seçip kullanımını ve sağlık gözetimini takip edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5 ve 9; Ek I: güvenli kullanım | Makina Emniyeti Yön.: Ek I: 1.5.8 | Standart/teknik: İşe özgü gürültü ölçümü; üretici verisi', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-031', 'bolum' => 'Torna', 'faaliyet' => 'Makine çevresinde yürüme', 'tehlike' => 'Soğutma sıvısı, yağ ve talaşlı zemin', 'risk' => 'Kayma, düşme ve kesilme', 'mevcut_onlem' => 'Kaçağı kaynağında giderin. Sıçrama bariyeri, uygun toplama ve düzenli temizlik kurun. Dökülmede alanı derhal ayırın ve temizleyin. Hortumları yürüyüş yolundan kaldırın; uygun kaymaz tabanlı ayakkabı sağlayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–9; Ek I–II: ilgili asgari kullanım koşulları | Makina Emniyeti Yön.: Ek I: 1.1.4, 1.3, 1.6, 1.7 (konuya göre) | Standart/teknik: ISO 12100; üretici yerleşim ve kullanım talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'TFD-032', 'bolum' => 'Torna', 'faaliyet' => 'Giysi ve kişisel donanım kullanımı', 'tehlike' => 'Gevşek giysi, takı, saç veya eldivenin dolanması', 'risk' => 'Kaptırma ve uzuv kaybı', 'mevcut_onlem' => 'Dönen elemanlara erişimi teknik olarak önleyin. Saçı toplayın, takı ve sarkan giysiyi kaldırın. Dönen takım yakınında eldiven kullanmayın. Keskin parçayı eldivenle taşıma işiyle dönen ekipmanın işletilmesini talimatta açıkça ayırın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-033', 'bolum' => 'Torna', 'faaliyet' => 'Yerleşim, temel ve sabitleme', 'tehlike' => 'Uygunsuz zemin, ankraj veya devrilme riski', 'risk' => 'Makinenin yer değiştirmesi, ezilme', 'mevcut_onlem' => 'Zemin taşıma kapasitesi, seviyeleme ve ankrajı üretici montaj planına göre doğrulayın. Servis açıklıkları ve taşıma güzergâhını koruyun. Taşıma veya yer değişiminden sonra bağlantıları ve güvenli çalışmayı kontrol ederek devreye alın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 40.0],
            ['kod' => 'TFD-034', 'bolum' => 'Torna', 'faaliyet' => 'Soğutma sıvısıyla işleme', 'tehlike' => 'Metal işleme sıvısı sisi ve sıçrama', 'risk' => 'Solunum yolu hastalığı', 'mevcut_onlem' => 'Daha az sis oluşturan sıvı ve proses seçeneğini değerlendirin. Kaynağında uygun yerel emiş ve sıçrama koruması sağlayın; açık tezgâhta kabin bulunduğunu varsaymayın. Emiş performansı ve maruziyeti değerlendirin; sağlık gözetimini planlayın. Solunum korumasını teknik kontrol yerine kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: gaz, buhar, sıvı ve toz yayılımı; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.5.13, 1.6 | Standart/teknik: HSE MW1–MW5; GBF; üretici sıvı/emiș talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-035', 'bolum' => 'Torna', 'faaliyet' => 'Soğutma sıvısıyla temas', 'tehlike' => 'Sıvı ve katkıların cilde bulaşması', 'risk' => 'Dermatit ve kimyasal tahriş', 'mevcut_onlem' => 'Teması kapalı besleme ve yardımcı araçlarla azaltın. Güvenlik bilgi formuna uygun cilt koruması ve hijyen düzeni kurun. Kirli giysiyi değiştirin; el temizliğinde çözücü kullanmayın. Eldiveni dönen parça yakınında kullanmayın; cilt yakınmalarını hekime bildirin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: gaz, buhar, sıvı ve toz yayılımı; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.5.13, 1.6 | Standart/teknik: HSE MW1–MW5; GBF; üretici sıvı/emiș talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'TFD-036', 'bolum' => 'Torna', 'faaliyet' => 'Su karışımlı sıvı bakımı', 'tehlike' => 'Mikrobiyal bozulma ve uygunsuz konsantrasyon', 'risk' => 'Solunum ve cilt hastalığı', 'mevcut_onlem' => 'Üreticiye uygun konsantrasyon, pH ve mikrobiyal kontrol programı oluşturun. Kaçak yağı ayırın; sonuçları kaydedin. Kokuya bakarak uygunluk kararı vermeyin. Biyosit eklemeyi yalnız uygun ürün, doz ve yetkili prosedürle yapın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: gaz, buhar, sıvı ve toz yayılımı; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.5.13, 1.6 | Standart/teknik: HSE MW1–MW5; GBF; üretici sıvı/emiș talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-037', 'bolum' => 'Torna', 'faaliyet' => 'Tank ve filtre temizliği', 'tehlike' => 'Kimyasal temas, sıçrama ve beklenmeyen pompa çalışması', 'risk' => 'Göz hasarı, hastalık, yaralanma', 'mevcut_onlem' => 'Pompa ve hareketli donanımı izole edin. Sıvıyı kontrollü boşaltın; GBF\'ye uygun ekipman, göz-yüz ve cilt koruması kullanın. Tanka insan girişi gerekiyorsa ayrı kapalı alan değerlendirmesi ve izin prosedürü tamamlanmadan giriş yaptırmayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: gaz, buhar, sıvı ve toz yayılımı; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.5.13, 1.6 | Standart/teknik: HSE MW1–MW5; GBF; üretici sıvı/emiș talimatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'TFD-038', 'bolum' => 'Torna', 'faaliyet' => 'Talaş ve sıvı atığı yönetimi', 'tehlike' => 'Keskin atık, sızıntı ve uyumsuz karışım', 'risk' => 'Kesilme, kayma ve yangın', 'mevcut_onlem' => 'Talaş türlerini ve yağlı atıkları uygun kaplarda ayırın. Kapasiteyi aşmayın; taşıma sırasında kapak ve güvenli boşaltma kullanın. Yanıcı metal talaşını uyumsuz sıvı ve diğer atıklarla karıştırmayın; atık alımını planlayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–9; Ek I–II: ilgili asgari kullanım koşulları | Makina Emniyeti Yön.: Ek I: 1.1.4, 1.3, 1.6, 1.7 (konuya göre) | Standart/teknik: ISO 12100; üretici yerleşim ve kullanım talimatı', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 7.0],
            ['kod' => 'TFD-039', 'bolum' => 'Torna', 'faaliyet' => 'Planlı kontrol ve bakım', 'tehlike' => 'Emniyet bileşenlerinin bozulmasının fark edilmemesi', 'risk' => 'Koruma kaybı, ağır yaralanma', 'mevcut_onlem' => 'Üretici talimatı, kullanım ve ortam şartlarına göre bakım/kontrol planı kurun. Koruyucu, durdurma, fren, bağlama ve izolasyon noktalarını kaydedin. Ek-III kapsamındaki yardımcı ekipman ve tesisatı ayrıca belirleyin; bakım ile mevzuata tabi periyodik kontrolü ayrı takip edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: hareketli parçalar, koruyucular; Ek II: genel kullanım | Makina Emniyeti Yön.: Ek I: 1.3, 1.4, 1.6, 1.7 | Standart/teknik: ISO 23125:2015; ISO 12100; üretici talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-040', 'bolum' => 'Torna', 'faaliyet' => 'Vardiya devri ve arıza bildirimi', 'tehlike' => 'Arızalı makinenin kullanılmaya devam edilmesi', 'risk' => 'Korumasız çalışma ve ağır yaralanma', 'mevcut_onlem' => 'Kritik arızada durdurma, kullanım dışı etiketleme ve yetkili yeniden devreye alma kuralını uygulayın. Açık DÖF, geçici düzenleme ve kilit durumunu vardiya devrinde yazılı aktarın. Üretim hedefi nedeniyle koruma iptaline izin vermeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 5–8; Ek I: kumanda, çalıştırma, durdurma ve koruyucular | Makina Emniyeti Yön.: Ek I: 1.2, 1.4 | Standart/teknik: ISO 23125:2015; ISO 13849-1; ISO 14119; ISO 13850 (ilgili işlev)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-121', 'bolum' => 'Torna', 'faaliyet' => 'İşe başlama ve yetkilendirme', 'tehlike' => 'Tezgâha özgü uygulama yeterliliğinin olmaması', 'risk' => 'Hatalı işletme ve ağır yaralanma', 'mevcut_onlem' => 'İlgili tezgâhın kumandası, durdurması ve güvenli iş sınırlarını uygulamalı öğretin. Çalışanı normal işletme, ayar ve bakım yetkileri bakımından ayrı değerlendirin. Gözetimli uygulama ve yeterlilik kontrolü sonrası yazılı yetkilendirin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 10–11: bilgilendirme ve eğitim | Makina Emniyeti Yön.: Ek I: 1.7.4 (talimatlar) | Standart/teknik: 6331: Md. 17; güncel eğitim mevzuatı; makine talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-122', 'bolum' => 'Torna', 'faaliyet' => 'Bağlama ve kesme parametresi eğitimi', 'tehlike' => 'Parça/takım kapasitesi ve hız sınırının bilinmemesi', 'risk' => 'Fırlama, kırılma ve ölüm', 'mevcut_onlem' => 'Parça, kesici ve tutucuya özgü bağlama yöntemini öğretin. Hız, ilerleme ve paso seçimini uygulamalı değerlendirin. Tornada ayna/çubuk desteğini, frezede mengene/pabuç bağlamasını ilgili çalışan üzerinde ayrı kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 10–11: bilgilendirme ve eğitim | Makina Emniyeti Yön.: Ek I: 1.7.4 (talimatlar) | Standart/teknik: 6331: Md. 17; güncel eğitim mevzuatı; makine talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-123', 'bolum' => 'Torna', 'faaliyet' => 'Kaptırma ve KKD eğitimi', 'tehlike' => 'Dönen parçada eldiven, bez veya ölçü aleti kullanılması', 'risk' => 'Kaptırma ve uzuv kaybı', 'mevcut_onlem' => 'Dönen parçada eldiven, bezle polisaj ve hareket halinde ölçme riskini öğretin. Hareketsiz keskin parçanın eldivenle taşınmasıyla işletimi ayırın. Saç, takı ve sarkan giysi kontrolünü makine başında değerlendirin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 10–11: bilgilendirme ve eğitim | Makina Emniyeti Yön.: Ek I: 1.7.4 (talimatlar) | Standart/teknik: 6331: Md. 17; güncel eğitim mevzuatı; makine talimatı', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'TFD-124', 'bolum' => 'Torna', 'faaliyet' => 'Bakım ve talaş temizliği eğitimi', 'tehlike' => 'Durdurmanın enerji izolasyonu sanılması', 'risk' => 'Beklenmeyen hareket, kesilme ve ölüm', 'mevcut_onlem' => 'Makineye özgü EKED adımlarını, tam duruşu ve sıfır enerji kontrolünü uygulatın. Talaşın elle alınmamasını, uygun kanca/fırça kullanımını ve grup kilitlemeyi öğretin. Bakım yetkisi olmayan kişinin arızaya müdahale etmemesini açıklayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 10–11: bilgilendirme ve eğitim | Makina Emniyeti Yön.: Ek I: 1.7.4 (talimatlar) | Standart/teknik: 6331: Md. 17; güncel eğitim mevzuatı; makine talimatı', 'olasilik' => 6.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-125', 'bolum' => 'Torna', 'faaliyet' => 'Sıvı, gürültü ve ergonomi eğitimi', 'tehlike' => 'Maruziyet belirtileri ve güvenli yöntemin bilinmemesi', 'risk' => 'Hastalık ve kas iskelet yaralanması', 'mevcut_onlem' => 'Sıvı GBF\'si, hijyen, emiş ve cilt/solunum yakınması bildirimini öğretin. Gürültü ve kaldırma yardımcılarını işe göre açıklayın. KKD seçimi ve kullanımını uygulamalı kontrol edin; teknik önlemlerin eğitimle ikame edilmesini önleyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 10–11: bilgilendirme ve eğitim | Makina Emniyeti Yön.: Ek I: 1.7.4 (talimatlar) | Standart/teknik: 6331: Md. 17; güncel eğitim mevzuatı; makine talimatı', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'TFD-126', 'bolum' => 'Torna', 'faaliyet' => 'Acil durum ve değişiklik eğitimi', 'tehlike' => 'Arıza/kaza veya yeni işte eski yöntemle devam edilmesi', 'risk' => 'İkincil kaza ve ağır yaralanma', 'mevcut_onlem' => 'Durdurma, güvenli uzaklaşma, haber verme ve ilk yardım sınırlarını öğretin. Yeni takım/malzeme ve olay sonrası talimatı güncelleyin. Eğitim tekrarı ve uygulama değerlendirmesini planlayın; katılım imzasını tek başına yeterlilik saymayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Madde 10–11: bilgilendirme ve eğitim | Makina Emniyeti Yön.: Ek I: 1.7.4 (talimatlar) | Standart/teknik: 6331: Md. 17; güncel eğitim mevzuatı; makine talimatı', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-139', 'bolum' => 'Torna', 'faaliyet' => 'Kaptırma veya sıkışma', 'tehlike' => 'Kurtarma sırasında hareketin devam etmesi', 'risk' => 'İkincil yaralanma ve ölüm', 'mevcut_onlem' => 'Acil durdurmayı kullanın ve enerjiyi güvenle ayırın. 112\'yi arayın; sıkışmış kişiyi rastgele ters hareket vererek çıkarmaya çalışmayın. Teknik kurtarma ve ilk yardım ekibini koordine edin; yük ve depolanmış enerji kontrol edilsin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-140', 'bolum' => 'Torna', 'faaliyet' => 'Takım veya parça fırlaması', 'tehlike' => 'Hasarlı tezgâhta üretime devam edilmesi', 'risk' => 'İkinci fırlama ve ağır yaralanma', 'mevcut_onlem' => 'Çalışmayı durdurun, alanı ayırın ve yaralıya eğitimli ilk yardımcı aracılığıyla destek sağlayın. Bağlama, takım ve muhafazayı yetkin ekip incelemeden yeniden başlatmayın. Olay nedenini kaydedip ilgili DÖF\'leri tamamlayın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-141', 'bolum' => 'Torna', 'faaliyet' => 'Elektrik çarpması', 'tehlike' => 'Enerji kesilmeden yaralıya temas', 'risk' => 'Kurtarıcının çarpılması ve ölüm', 'mevcut_onlem' => 'Enerjiyi güvenli noktadan ayırın, 112\'ye haber verin. Canlı bölüme veya yaralıya doğrudan dokunmayın. Güvenli ortam sağlanınca eğitimli ilk yardımcı müdahale etsin; arıza giderilip test edilmeden makine çalıştırılmasın.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 1.0, 'siddet' => 40.0],
            ['kod' => 'TFD-142', 'bolum' => 'Torna', 'faaliyet' => 'Yangın veya duman', 'tehlike' => 'Uygunsuz söndürme ve gecikmiş tahliye', 'risk' => 'Yanık, duman maruziyeti ve ölüm', 'mevcut_onlem' => 'Alarm verin, güvenliyse enerjiyi ayırın ve alanı boşaltın. Yağ, elektrik ve varsa yanıcı metal için uygun müdahale yöntemini önceden belirleyin. Eğitimli ekip güvenli sınır dışında müdahale etmesin; 112\'ye ekipman/malzeme bilgisini iletin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
            ['kod' => 'TFD-143', 'bolum' => 'Torna', 'faaliyet' => 'Sıvı sıçraması veya dökülmesi', 'tehlike' => 'Kimyasal temas ve kaygan alana kontrolsüz giriş', 'risk' => 'Göz/cilt hasarı ve düşme', 'mevcut_onlem' => 'GBF\'ye uygun göz/cilt yıkama erişimi sağlayın. Maruziyette GBF ilk yardım bilgisini ve sağlık yönlendirmesini izleyin. Alanı ayırıp uygun emiciyle eğitimli personele temizletin; makine kaçağı giderilmeden normal kullanıma dönmeyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 15.0],
            ['kod' => 'TFD-144', 'bolum' => 'Torna', 'faaliyet' => 'Kesinti, deprem ve tahliye', 'tehlike' => 'Beklenmeyen yeniden başlatma veya engelli kaçış', 'risk' => 'Çarpılma, ezilme ve tahliye gecikmesi', 'mevcut_onlem' => 'Güvenli uzaklaşmayı ve açık kaçış yolunu sağlayın. Kesinti/deprem sonrası bağlama, enerji ve yapısal hasarı yetkili ekip kontrol etsin. Enerji dönüşü tek başına çalıştırma oluşturmasın; sayım ve yeniden başlatma sorumlusunu belirleyin.', 'mevzuat' => 'İş Ekipmanları Yön.: Ek I: durdurma, enerji ayırma ve ilgili koruma; Madde 5–8 | Makina Emniyeti Yön.: Ek I: 1.2.4, 1.5, 1.7 (ilgili tehlike) | Standart/teknik: 6331: Md. 11–12; işyeri acil durum planı; GBF', 'olasilik' => 3.0, 'frekans' => 2.0, 'siddet' => 40.0],
        ]],
        'atolye_sutunlu_matkap' => ['Atölye – Sütunlu matkap', [
            ['kod' => 'MAK-083', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Mandren bölgesi', 'tehlike' => 'Dönen mandrene doğrudan erişim', 'risk' => 'El/giysi kapılması', 'mevcut_onlem' => 'İşleme uygun mandren ve işlem bölgesi koruyucusu sağlayın. Görüş ve bağlamayı koruyacak biçimde ayarlayın; tehlikeli dönme sürerken korumayı açarak müdahale etmeyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-084', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Parça bağlama', 'tehlike' => 'Parçanın elle tutulması', 'risk' => 'Parçanın dönmesi, el yaralanması', 'mevcut_onlem' => 'Parçayı uygun mengene veya bağlama aparatına alın. Mengenenin tabla bağlantısını da sabitleyin; küçük parça için özel aparat kullanın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-085', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Mandren anahtarı', 'tehlike' => 'Anahtarın takılı unutulması', 'risk' => 'Fırlama ve ağır yaralanma', 'mevcut_onlem' => 'Kendiliğinden çıkan uygun anahtar kullanın. Anahtarı ayrı yuvaya kaldırın; delme öncesi anahtar ve bağlama kontrolü yapın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-086', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Matkap ucu', 'tehlike' => 'Yanlış devir, körelmiş veya çatlak uç', 'risk' => 'Uç kırılması ve göz yaralanması', 'mevcut_onlem' => 'Çap ve malzemeye uygun devir/ilerleme seçin. Hasarlı ucu değiştirin; çıkışta ani yüklenmeyi önlemek için uygun destek kullanın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-087', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Derin delik', 'tehlike' => 'Talaşın uç çevresinde birikmesi', 'risk' => 'Sıkışma, parça savrulması', 'mevcut_onlem' => 'Uygun talaş boşaltma adımlarını uygulayın. Talaşı duruşta fırça veya kancayla alın; dönen ucu elle veya bezle temizlemeyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-088', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Eldiven ve giysi', 'tehlike' => 'Dönen uca eldiven/kol kaptırma', 'risk' => 'Uzuv kaybı', 'mevcut_onlem' => 'Dönen mil yakınında eldiven, takı ve bol giysi kullanımını önleyin. Keskin parça taşımayı tam duruş ve güvenli durumdan sonra uygun eldivenle yapın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-089', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Tablanın ayarı', 'tehlike' => 'Gevşek tabla veya yükseklik kilidi', 'risk' => 'Tablanın düşmesi ve ezilme', 'mevcut_onlem' => 'Tabla ve başlık kilitlerini kontrol edin. Yükseklik ayarını yükü güvenli destekleyerek yapın; aşınmış kilit mekanizmasını onarın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'MAK-090', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Kayış kapağı', 'tehlike' => 'Tahrik bölgesine erişim', 'risk' => 'Kapılma', 'mevcut_onlem' => 'Kayış-kasnak kapağını sağlam tutun. Devir kayışı değişiminde enerjiyi kilitleyin; bakım sonrası kapak ve varsa kilitleme işlevini kontrol edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'MAK-091', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Tezgâh stabilitesi', 'tehlike' => 'Makinenin sallanması veya devrilmesi', 'risk' => 'Ezilme', 'mevcut_onlem' => 'Taban ve zeminin uygunluğunu kontrol edin. Üreticinin bağlantı şartlarını uygulayın; uygunsuz zemin ve gevşek bağlantıyı onarmadan kullanmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 3.0, 'frekans' => 3.0, 'siddet' => 15.0],
            ['kod' => 'MAK-092', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Makineye asılı hortum', 'tehlike' => 'Hortum veya kablonun dönen bölgeye yaklaşması', 'risk' => 'Kapılma ve takılma', 'mevcut_onlem' => 'Hortumları sabit askı/kanala alın. Mandren hareket alanından uzaklaştırın; çalışma stroku boyunca kablo gerilmesi olmadığını doğrulayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-093', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Dayalı merdiven', 'tehlike' => 'Merdivenin tezgâh üzerine devrilmesi', 'risk' => 'Çarpma ve denge kaybı', 'mevcut_onlem' => 'Merdiveni kullanım dışında sabitlenmiş depolama yerine alın. Tezgâha ve elektrik donanımına dayalı bırakmayın; makine çevresini temiz tutun.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
            ['kod' => 'MAK-094', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Priz ve kablo', 'tehlike' => 'Sarkan bağlantının çekilmesi veya hasarı', 'risk' => 'Elektrik çarpması', 'mevcut_onlem' => 'Prizi uygun sabit noktaya taşıyın. Kabloyu çekme ve ezilmeye karşı koruyun; hasarlı fiş/prizleri yetkili elektrik personeline değiştirin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 40.0],
            ['kod' => 'MAK-095', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Durdurma', 'tehlike' => 'Butona erişilememesi veya istemsiz başlatma', 'risk' => 'Kapılma ve ezilme', 'mevcut_onlem' => 'Kumandaları erişilebilir ve yanlışlıkla çalıştırmaya karşı korumalı düzenleyin. Stop önceliğini ve enerji dönüşünde kendiliğinden başlamama işlevini test edin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 13850 (acil stop işlevi için)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 15.0],
            ['kod' => 'MAK-096', 'bolum' => 'Sütunlu matkap', 'faaliyet' => 'Delme sırasında kuvvet', 'tehlike' => 'Aşırı bastırma ve uygunsuz çalışma yüksekliği', 'risk' => 'Kas-iskelet zorlanması', 'mevcut_onlem' => 'Tabla yüksekliğini işe uygun ayarlayın. Uygun kesici ve ilerlemeyle zorlamayı azaltın; tekrarlı işlerde destek fikstürü ve iş organizasyonu düzenleyin.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I (makineyle ilişkili kısım); Makina Emniyeti Yön. Ek-I; ISO 12100 (makineyle ilişkili risklerde)', 'olasilik' => 3.0, 'frekans' => 6.0, 'siddet' => 7.0],
        ]],
        'atolye_kesme_tezgahi' => ['Atölye – Kesme tezgâhı', [
            ['kod' => 'MAK-097', 'bolum' => 'Kesme tezgâhı', 'faaliyet' => 'Kesici koruması', 'tehlike' => 'Disk/bıçak bölgesine erişim', 'risk' => 'Kesilme ve uzuv kaybı', 'mevcut_onlem' => 'Kesici tipini doğrulayıp uyumlu sabit/hareketli koruyucuları tamamlayın. Koruyucunun kesim hareketi boyunca korumayı sürdürmesini test edin; iptal edilmiş sistemle çalışmayın.', 'mevzuat' => 'İş Ekipmanları Yön. Ek-I; Makina Emniyeti Yön. Ek-I; ISO 12100; ISO 14120 (koruyucu varsa)', 'olasilik' => 6.0, 'frekans' => 6.0, 'siddet' => 15.0],
